  const presentation=window.CommerceCatalogPresentation||{storeLabel:d=>d.store_identity?.label||(d.kind==='candidate'?'调研候选 · 尚未绑定店铺':'店铺身份待核对'),scopes:()=>'',field:f=>e(f.original||'未提供'),textBlock:v=>e(v||'未提供')};
