/* Order handoff is data only. The service rechecks every snapshot before saving. */
window.CommerceOrderSupportContext=()=>{
 const copy=value=>JSON.parse(JSON.stringify(value));
 const businessScope=context=>({platform:context.scope.platform,store_ref:context.scope.store_id,subject_ref:context.order.order_id});
 const scopeKey=context=>JSON.stringify(Object.values(businessScope(context)));
 const eligible=(source,context)=>{const doc=source.document||source,s=businessScope(context);return ['conversation','facts'].includes(doc.kind)&&doc.synthetic===context.scope.demo&&doc.scope?.platform===s.platform&&doc.scope?.store_ref===s.store_ref&&doc.scope?.subject_ref===s.subject_ref};
 function receive(prepared){
  const c=prepared?.context,s=c?.scope,o=c?.order;
  if(prepared?.external_execution_allowed!==false||c?.schema!=='commerce-order-support-context-v1'||typeof s?.demo!=='boolean'||!['ozon','tiktok','amazon','mercado','temu','local'].includes(s.platform)||typeof s.store_id!=='string'||!s.store_id.trim()||s.store_id==='all'||!/^([A-Z]{2})$/.test(s.market)||typeof o?.id!=='string'||!o.id.trim()||typeof o.order_id!=='string'||!o.order_id.trim()||![o.source_sha256,o.record_sha256,c.context_sha256].every(v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v)))throw Error('order_support_invalid_context');
  return copy(c);
 }
 function selected(sources,context){
  if(!sources.some(s=>s.document.kind==='conversation'))throw Error('order_support_conversation_required');
  if(!sources.some(s=>s.document.kind==='facts'))throw Error('order_support_facts_required');
  for(const source of sources){
   if(!eligible(source,context))throw Error('order_support_scope_mismatch');
   if(!source.fresh)throw Error('order_support_source_stale');
   if(source.document.kind==='facts'){
    const facts=Object.fromEntries(source.document.records.map(row=>[row.key,row.value]));
    if(facts.order_ref!==context.order.order_id)throw Error('order_support_order_mismatch');
    if(facts.market!==context.scope.market)throw Error('order_support_market_mismatch');
   }
  }
 }
 function request(context,sources,content,previous){
  selected(sources,context);
  if(content.fields.conversation_ref!==context.order.order_id)throw Error('order_support_order_mismatch');
  return {context:copy(context),source_refs:sources.map(s=>({id:s.id,version:s.version,sha256:s.sha256})),content,
   ...(previous?{parent_id:previous.id,expected_parent_sha256:previous.draft.draft_sha256}:{})};
 }
 return {receive,businessScope,scopeKey,eligible,selected,request};
};
/* Private evidence intake and immutable local drafts; shared by browser and Harness. */
window.CommerceBusiness=({api,esc,toast,repaint,modal,closeModal,isActive})=>{
 const ui=window.CommerceUI,forms=window.CommerceBusinessForms({ui}),orderSupport=window.CommerceOrderSupportContext?.();
 const state={page:'reviews',synthetic:false,board:null,selected:new Set(),draft:null,error:'',busy:false,generation:0,editor:null,writeKeys:new Map(),editorRequest:0,editorPending:false,orderContext:null};
 const kinds={reviews:'评论资料',conversation:'客服会话',facts:'业务事实',review:'评论分析',support:'客服回复',listing:'上架草稿',price:'改价草稿',shipping:'发货草稿',refund:'退款草稿',purchase:'采购草稿',advertising:'广告草稿'};
 const statuses={analysis:'规则分析已生成',ready_for_review:'可作本地审阅',needs_input:'资料待补',stale:'依据已变化或过期',invalid:'依据校验失败',local_review_recorded:'已记录本地审阅',rejected:'本地已驳回',review_expired:'本地审阅已过期'};
 const fields={sku:'SKU',title:'商品名称',description:'商品说明',category_id:'平台类目',price:'价格',currency:'币种',quantity:'数量',image_refs:'图片来源',order_ref:'订单引用',package_ref:'包裹引用',carrier:'承运商',tracking_number:'运单号',amount:'金额',reason:'原因',unit_cost:'单位成本',supplier_ref:'供应商引用',campaign_ref:'广告活动引用',budget:'预算',market:'市场',start_at:'开始时间',end_at:'结束时间',conversation_ref:'会话引用',reply:'回复正文',policy_ref:'规则引用'};
 const errors={order_support_invalid_context:'订单接续来源无效，请从订单详情重新核对；当前输入已保留。',order_support_editor_open:'当前编辑器仍有内容，请先保存或关闭，再打开另一订单。',order_support_scope_mismatch:'订单平台、店铺、对象或输入范围不一致，请核对后重新选择；当前输入已保留。',order_support_source_changed:'订单快照或所选资料版本已变化，请重新核对后建立新版；当前输入已保留。',order_support_source_stale:'订单或所选资料已过期，请先核对新来源；当前输入已保留。',order_support_scope_unconfirmed:'请先在店铺连接中确认订单范围，再从原订单起草客服回复。',order_support_source_unavailable:'原订单来源已不可用，请返回订单核对；当前输入已保留。',order_support_conversation_required:'请选择已导入的同订单客服会话，不会自动创建客户会话。',order_support_facts_required:'请选择已导入的同订单事实，须包含order_ref、market与回复依据。',order_support_market_mismatch:'所选事实的market须与固定订单市场完全相同；当前输入已保留。',order_support_order_mismatch:'所选事实的order_ref或会话引用须与固定订单号完全相同；当前输入已保留。',order_support_bound_draft_required:'此草稿已绑定订单，请从订单接续编辑新版；当前输入已保留。',order_support_parent_changed:'原草稿或订单绑定不一致，请重新读取核对；当前输入已保留。',business_invalid_quantity:'数量应为非负整数，当前输入已保留。',business_invalid_boolean:'布尔值应为true或false，当前输入已保留。',business_editor_loading:'正在读取所选类型，请稍后保存。',business_scope_mismatch:'所选资料的平台、店铺、对象或合成标记不同，请分别处理。',business_version_conflict:'资料已更新，请刷新后再导入新版。',business_scope_immutable:'更新资料须保持原平台、店铺、对象及合成标记。不同范围请作为新资料导入。',business_preflight_incomplete:'资料或引用尚未完整，或来源已过期。请核对后建立新版草稿。',business_idempotency_conflict:'请求标识与上次内容不一致，请重新打开编辑器。',business_draft_changed:'草稿哈希不匹配，请重新读取。',business_reviews_required:'评论分析只能选评论资料。',business_invalid_document:'资料字段不完整或格式错误，请使用标准模板。',business_invalid_validity:'来源时间或有效期不正确，有效期最长31天，来源时间不能在未来。',business_invalid_origin:'来源须为不含账号、参数的 HTTPS 链接，或 private-export:文件名。',business_invalid_rating:'评分只支持1至5的整数或null。',business_explicit_local_review_required:'请先勾选已核对当前草稿和引用。'};
 const message=e=>errors[e.message]||'操作未完成。请检查格式、范围和服务状态；当前编辑内容已保留。';
 const button=(label,action,attrs={})=>ui.button({label,attrs:{'data-business-action':action,...attrs}});
 const json=x=>esc(JSON.stringify(x,null,2));
 const scope=s=>`${s.platform} · ${s.store_ref||'店铺未知'} · ${s.subject_ref}`;
 const selected=()=>state.board?.sources.filter(s=>state.selected.has(s.id))||[];
 const active=()=>isActive();
 function download(filename,content){const url=URL.createObjectURL(new Blob([content],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
 async function write(tool,args){const signature=tool+JSON.stringify(args);let key=state.writeKeys.get(signature);if(!key){key=crypto.randomUUID();state.writeKeys.set(signature,key)}const result=await api(tool,{...args,idempotency_key:key});state.writeKeys.delete(signature);return result}
 async function refresh(generation=state.generation){const board=await api('commerce_business_list',{synthetic:state.synthetic});if(generation!==state.generation)return;const draftId=state.draft?.id,draft=draftId?await api('commerce_business_get',{draft_id:draftId}):null;if(generation!==state.generation)return;state.board=board;state.selected=new Set([...state.selected].filter(id=>board.sources.some(s=>s.id===id)));if(draftId===state.draft?.id)state.draft=draft}
 async function enter(page){cancelEditor();if(page!=='support')state.orderContext=null;if(state.page!==page){state.page=page;state.selected.clear();state.draft=null;state.sourceScope='';state.sourceQuery='';state.sourceKind=page==='support'?'conversation':'reviews';state.sourceLimit=8}const generation=++state.generation;state.error='';try{await refresh(generation)}catch(e){if(generation===state.generation)state.error=message(e)}if(generation===state.generation&&active())repaint()}
 state.sourceQuery='';state.sourceScope='';state.sourceKind='reviews';state.sourceLimit=8;
 const scopeKey=value=>JSON.stringify([value.platform,value.store_ref??null,value.subject_ref]);
 const sourceSearch=source=>[source.label,kinds[source.kind]||source.kind,scope(source.scope),source.origin_ref].join(' ').toLowerCase();
 const inSourceScope=source=>!!state.sourceScope&&scopeKey(source.scope)===state.sourceScope&&(!state.orderContext||orderSupport?.eligible(source,state.orderContext));
 const sourceRows=()=> (state.board?.sources||[]).filter(source=>inSourceScope(source)&&(state.sourceKind==='all'||source.kind===state.sourceKind)&&sourceSearch(source).includes(state.sourceQuery.trim().toLowerCase()));
 const selectionReady=()=>selected().length>0&&selected().every(inSourceScope)&&(!state.orderContext||(selected().some(s=>s.kind==='conversation')&&selected().some(s=>s.kind==='facts')));
 const sourceSummary=()=> '匹配 '+sourceRows().length+' 条 · 已选 '+state.selected.size+' 条'+(state.selected.size?'（保留同范围筛选外选择）':'');
 function sourceResults(){const rows=sourceRows();if(!state.sourceScope)return ui.empty('请选择平台、店铺与对象范围。');if(!rows.length)return ui.empty(state.orderContext?'此订单暂无匹配资料。请导入同订单会话和事实；事实需包含order_ref及market。':'当前范围与类型没有匹配资料。可切换类型、范围或导入资料。');return ui.table(['资料','操作'],rows.slice(0,state.sourceLimit).map(source=>`<tr data-business-source-row><td><label class="business-source-label"><input type="checkbox" id="business-source-${esc(source.id)}" data-business-source="${esc(source.id)}" ${state.selected.has(source.id)?'checked':''} ${state.busy?'disabled':''}><span>${esc(source.label)}<br><small>${esc(kinds[source.kind]||source.kind)} · ${source.record_count}条 · v${source.version} · ${source.fresh?'有效期内，待核实':'已过期'}</small></span></label><details><summary>来源与时间</summary><p>${esc(source.origin_ref)}<br>${esc(new Date(source.observed_at).toLocaleString())}</p></details></td><td>${button('原资料','source',{'data-id':source.id,disabled:state.busy})}</td></tr>`))+(rows.length>state.sourceLimit?button('再显示8条','source-more',{disabled:state.busy}):'')}
 document.addEventListener('input',event=>{if(event.target.id!=='business-source-query')return;state.sourceQuery=event.target.value.slice(0,120);state.sourceLimit=8;const results=document.getElementById('business-source-results');if(results)results.innerHTML=sourceResults();const result=document.getElementById('business-source-result');if(result)result.textContent=sourceSummary()});
 function sourceList(){const rows=(state.board?.sources||[]).filter(source=>!state.orderContext||orderSupport?.eligible(source,state.orderContext)),scopes=[...new Map(rows.map(source=>[scopeKey(source.scope),source.scope])).entries()];if(state.orderContext&&!scopes.length)scopes.push([state.sourceScope,orderSupport.businessScope(state.orderContext)]);return `<section class="card"><div class="business-heading"><h2>资料选择</h2><div class="business-actions">${button('导入资料','import',{disabled:state.busy})}${button('标准模板','template',{disabled:state.busy})}</div></div><div class="business-actions">${ui.field('平台、店铺与对象范围',ui.select({id:'business-source-scope',disabled:state.busy||!!state.orderContext,value:state.sourceScope,options:[{value:'',label:'请选择范围'},...scopes.map(([value,range])=>({value,label:scope(range)}))]}))}${ui.field('资料类型',ui.select({id:'business-source-kind',disabled:state.busy,value:state.sourceKind,options:[{value:'reviews',label:'评论资料'},{value:'conversation',label:'客服会话'},{value:'facts',label:'业务事实'},{value:'all',label:'全部类型（主动查找）'}]}))}</div><p class="muted" data-business-source-scope>${state.sourceScope?esc(scope(scopes.find(([key])=>key===state.sourceScope)?.[1]||{}))+' · ':''}${state.synthetic?'合成示例':'本机真实输入，来源未独立核实'}${state.orderContext?' · 订单范围已固定':''}</p><div class="business-source-filter">${ui.field('搜索当前范围资料',ui.input({id:'business-source-query',type:'search',value:state.sourceQuery,maxlength:120,placeholder:'名称或来源'}))}<span id="business-source-result" role="status">${sourceSummary()}</span></div><div id="business-source-results" class="business-source-table" role="region" aria-label="业务来源资料列表" tabindex="0">${sourceResults()}</div><div class="business-actions">${button('清空选择','clear-selection',{disabled:state.busy||!state.selected.size})}${state.page==='reviews'?button('分析所选评论','analyze',{disabled:state.busy||!selectionReady()||selected().some(source=>source.kind!=='reviews')}):''}${button(state.page==='support'?'新建回复草稿':'新建经营草稿','compose',{disabled:state.busy||!selectionReady()})}</div></section>`}
 function citationCaption(ref){const source=state.board?.sources.find(s=>s.id===ref.source_id);return [(source&&kinds[source.kind])||'资料',fields[ref.key]||ref.key,'#'+String(ref.source_id).slice(-8)].join(' · ')}
 function draftChecks(p){const issues=[['缺少字段',p.missing_fields],['格式待修正',p.invalid_fields],['引用不匹配',p.uncited_fields]].filter(([,list])=>list.length);return issues.length?issues.map(([name,list])=>`<p><strong>${name}：</strong>${list.map(k=>esc(fields[k]||k)).join('、')}</p>`).join(''):'<p>字段、格式与引用检查通过。</p>'}
 function resultView(){const d=state.draft;if(!d)return '';const e=d.draft,p=d.preflight,c=e.content;let body='';
  if(e.kind==='review')body=`<p>输入 ${c.total_records} 条；缺少评分 ${c.missing_rating} 条；主题未命中 ${c.unmatched} 条。</p><p class="muted">${esc(c.notice)}</p>${ui.table(['主题','命中条数','原文引用'],c.topics.map(t=>`<tr><td>${esc(t.label)}</td><td>${t.count}</td><td>${t.evidence.map(q=>`<details><summary>${esc(q.record_id)} · v${q.version}</summary><p>${esc(q.quote)}</p><small>来源 ${esc(q.source_id)}</small></details>`).join('')}${t.evidence_truncated?'<p>仅展示前20条依据，完整原资料可在来源查看。</p>':''}</td></tr>`))}<details><summary>评分分布</summary><pre>${json(c.rating_counts)}</pre></details>`;
  else body=`${ui.table(['字段','当前草稿值','依据'],Object.entries(c.fields).map(([key,value])=>`<tr><th scope="row">${esc(fields[key]||key)}</th><td class="business-value">${esc(typeof value==='string'?value:JSON.stringify(value))}</td><td>${key==='reply'?'人工编辑，须逐句核对':c.citations[key]?esc(citationCaption(c.citations[key])):key==='conversation_ref'?'所选会话对象':'缺少字段引用'}</td></tr>`))}<div class="business-checks" role="status">${draftChecks(p)}<p>店铺范围：${p.store_scope_known?'已明确填写':'尚未知'} · 平台规则与文案准确性：待人工核对</p></div><div class="business-actions">${button('编辑为新版草稿','edit',{disabled:state.busy})}${button('记录本地审阅','review',{disabled:state.busy||!p.ready_for_local_review})}${button('驳回草稿','reject',{disabled:state.busy})}</div>`;
  return `<section class="card business-result"><div class="business-heading"><h2>${esc(kinds[e.kind])} ${ui.badge(statuses[d.status]||d.status,'gray')}</h2>${button('导出私有证据','export',{disabled:state.busy})}</div><p>${esc(scope(e.scope))} · ${e.synthetic?'合成输入':'真实输入，未独立核实'}</p>${p.status!=='current'?ui.alert('来源已更新、过期或校验未通过。请核对当前资料并保存新版；旧版本证据仍保留。'):''}${body}<details><summary>引用版本与草稿哈希</summary><pre>${json({sources:e.sources,draft_sha256:e.draft_sha256})}</pre></details>${d.receipts.length?`<details><summary>本地审阅记录（${d.receipts.length}）</summary><pre>${json(d.receipts)}</pre></details>`:''}<p class="muted" data-ui-help>本地审阅有效期15分钟，仅记录当前草稿；任何状态均不会向平台执行或向买家发送。</p></section>`;
 }
 function view(page){const list=state.board?.drafts||[];return `<div class="business-root"><section class="card"><div class="business-heading"><h2>${page==='support'?'客服会话与回复':'评论分析与经营草稿'}</h2>${button('刷新资料与状态','refresh',{disabled:state.busy})}</div><div class="business-actions">${ui.field('输入范围',ui.select({id:'business-mode',disabled:state.busy||!!state.orderContext,value:state.synthetic?'synthetic':'real',options:[{value:'real',label:'真实输入'},{value:'synthetic',label:'合成示例输入'}]}))}</div><p class="muted" data-ui-help>仅保存本机分析与草稿，不自动发送消息或写入平台。</p></section>${state.error?ui.alert(esc(state.error),'danger'):''}${state.busy?'<p role="status" aria-live="polite">正在保存或读取，请稍候…</p>':''}${orderContextView()}${sourceList()}${resultView()}<section class="card"><h2>本机分析与草稿历史</h2>${list.length?ui.table(['类型','范围','当前状态','操作'],list.map(d=>`<tr><td>${esc(kinds[d.kind])}</td><td>${esc(scope(d.scope))}</td><td>${esc(statuses[d.status]||d.status)}</td><td>${button('打开','open',{'data-id':d.id,disabled:state.busy})}</td></tr>`)):ui.empty('尚无分析或草稿。')}</section></div>`}
 function orderContextView(){const c=state.orderContext;if(!c)return '';return `<section class="card"><div class="business-heading"><h2>订单客服接续</h2>${button('退出订单接续','order-context-clear',{disabled:state.busy})}</div><p>${esc(c.scope.platform)} · ${esc(c.scope.store_id)} · ${esc(c.scope.market)} · 订单 ${esc(c.order.order_id)}${c.order.line_id?' · 行 '+esc(c.order.line_id):''}</p><p class="muted">${c.order.import_batch_id?'本机CSV导入，来源未独立核实':'已读取订单快照'}。选择同订单已导入会话和事实；不会创建会话或发送消息。</p><details><summary>固定来源快照</summary><pre>${json(c)}</pre></details></section>`}
 async function enterOrderSupport(prepared){
  if(state.busy||state.editorPending||document.querySelector('.dialog'))throw Error('order_support_editor_open');
  if(!orderSupport)throw Error('order_support_invalid_context');
  const context=orderSupport.receive(prepared);if(state.page==='support'&&state.orderContext?.context_sha256===context.context_sha256){const generation=++state.generation;try{await refresh(generation)}catch(e){if(generation===state.generation)state.error=message(e)}if(generation===state.generation&&active())repaint();return}cancelEditor();state.page='support';state.synthetic=context.scope.demo;state.orderContext=context;state.sourceScope=orderSupport.scopeKey(context);state.sourceKind='conversation';state.sourceQuery='';state.sourceLimit=8;state.selected.clear();state.draft=null;state.error='';const generation=++state.generation;
  try{await refresh(generation)}catch(e){if(generation===state.generation)state.error=message(e)}
  if(generation===state.generation&&active())repaint();
 }
 async function importEditor(document=null,source=null,kind=null){
  const ticket=beginEditor();try{
  const selected=kind||(state.page==='support'?'conversation':'reviews');
  if(!document){document=(await api('commerce_business_template',{kind:selected})).document;if(!state.synthetic){document={...document,synthetic:false,label:'',origin_ref:'',observed_at:'',valid_until:'',scope:{platform:'ozon',store_ref:null,subject_ref:''},records:selected==='reviews'?[{id:'record-1',text:'',rating:null}]:selected==='conversation'?[{id:'record-1',role:'buyer',text:''}]:document.records.map(r=>({...r,value:''}))}}}
  if(state.orderContext&&!source)document={...document,synthetic:state.synthetic,scope:orderSupport.businessScope(state.orderContext)};
  if(!editorCurrent(ticket))return;
  state.editor={type:'import',source,document,formKind:selected};
  modal(source?'更新资料版本':'导入私有业务资料',`<p data-ui-help>保留来源、时间、店铺和对象。使用脱敏引用，去除昵称、联系方式、地址及凭据。导入仅留存资料，不代表核实。</p><p>当前范围：${state.synthetic?'合成示例输入':'真实输入'}。</p>${source?'':ui.field('资料类型',ui.select({id:'business-import-kind',value:selected,options:['reviews','conversation','facts','price','listing','shipping','refund','purchase','advertising','support'].map(value=>({value,label:({reviews:'评论',conversation:'客服会话',facts:'通用事实',price:'价格事实',listing:'商品事实',shipping:'物流事实',refund:'退款依据',purchase:'采购依据',advertising:'广告依据',support:'客服依据'})[value]||value}))}))}${forms.importEditor(document)}<div class="form-actions">${button('添加一条记录','record-add')}</div><details class="business-advanced"><summary>高级：导入文件或编辑JSON</summary><p data-ui-help>勾选后保存使用JSON；字段表单暂不参与保存。文件上限450KB。</p><label><input type="checkbox" id="business-import-advanced">使用高级JSON内容</label><label class="field">选择JSON文件<input id="business-file" type="file" accept=".json,application/json"></label><label class="field">资料JSON<textarea id="business-import-json" class="ui-control business-editor" spellcheck="false">${json(document)}</textarea></label></details><p id="business-modal-error" role="alert"></p>`,button('保存至本机','import-save',{id:'business-import-save'}))
 }finally{endEditor(ticket)}
 }

 async function compose(kind=null,previous=null){const ticket=beginEditor();try{const ids=previous?previous.draft.sources.map(s=>s.id):[...state.selected];const sources=await Promise.all(ids.map(source_id=>api('commerce_business_source_get',{source_id})));const boundContext=previous?.order_context?.context||state.orderContext;const currentKind=boundContext?'support':kind||(state.page==='support'?'support':'price');if(boundContext)orderSupport.selected(sources,boundContext);const template=await api('commerce_business_template',{kind:currentKind});let content=previous?previous.draft.content:{fields:{},citations:{}};
  if(!previous){for(const s of sources){if(s.document.kind!=='facts')continue;for(const row of s.document.records){if(Object.hasOwn(template.required_fields,row.key)&&!Object.hasOwn(content.fields,row.key)){content.fields[row.key]=row.value;content.citations[row.key]={source_id:s.id,key:row.key}}}}if(currentKind==='support'){const conv=sources.find(s=>s.document.kind==='conversation');if(conv)content.fields.conversation_ref=conv.document.scope.subject_ref;if(!content.fields.reply)content.fields.reply=''}}
  if(!editorCurrent(ticket))return;
  state.editor={type:'draft',ids,kind:currentKind,parent:previous?.id,previous,content,sources,template,orderContext:boundContext};modal('编辑'+kinds[currentKind],`<p>引用 ${sources.length} 份资料。字段来自所选资料，仍需逐项核对。回复正文由操作者编辑，系统不核实其承诺或规则。</p>${previous||boundContext?'':ui.field('草稿类型',ui.select({id:'business-kind',value:currentKind,options:Object.keys(kinds).filter(k=>!['review','reviews','conversation','facts'].includes(k)).map(k=>({value:k,label:kinds[k]}))}))}${forms.draftEditor(template,content,sources,{readonlyFields:boundContext?['conversation_ref']:[]})}<details class="business-advanced"><summary>高级：草稿JSON</summary><label><input type="checkbox" id="business-content-advanced">使用高级JSON内容</label><p>勾选后保存以JSON为准；字段表单不参与保存。</p><label class="field">草稿内容与引用JSON<textarea id="business-content-json" class="ui-control business-editor" spellcheck="false">${json(content)}</textarea></label></details><p id="business-modal-error" role="alert"></p>`,button('保存新版草稿','draft-save',{id:'business-draft-save'}))}finally{endEditor(ticket)}}
 async function execute(b){const action=b.dataset.businessAction;if(action==='order-context-clear'){state.orderContext=null;state.sourceScope='';state.selected.clear();state.draft=null;return}if(action==='clear-selection'){state.selected.clear();return}if(action==='source-more'){state.sourceLimit+=8;return}if(['analyze','compose'].includes(action)&&!selectionReady())throw Error('business_scope_mismatch');if(action==='analyze'&&selected().some(source=>source.kind!=='reviews'))throw Error('business_reviews_required');if(state.editorPending&&['import-save','draft-save'].includes(action))throw Error('business_editor_loading');
  if(action==='refresh'){await refresh();state.error=''}
  else if(action==='template'){const kind=state.page==='support'?'conversation':'reviews';const r=await api('commerce_business_template',{kind});modal('标准资料模板',`<p>${esc(r.notice)}</p><p data-ui-help>合成模板保留synthetic=true。真实资料需显式填写synthetic=false及真实范围。</p><div class="business-actions">${['reviews','conversation','facts'].map(k=>button('下载'+kinds[k]+'模板','download-template',{'data-kind':k})).join('')}</div><pre>${json(r.document)}</pre>`)}
  else if(action==='download-template'){const t=await api('commerce_business_template',{kind:b.dataset.kind});download('business-'+b.dataset.kind+'-synthetic-template.json',JSON.stringify(t.document,null,2))}
  else if(action==='import')await importEditor();
  else if(action==='record-add'){const e=state.editor,doc=forms.importValue(e.document);if(doc.records.length>=1000)throw Error('business_record_limit');doc.records.push(doc.kind==='reviews'?{id:'record-'+crypto.randomUUID(),text:'',rating:null}:doc.kind==='conversation'?{id:'record-'+crypto.randomUUID(),role:'buyer',text:''}:{key:'',value:''});await importEditor(doc,e.source,e.formKind)}
  else if(action==='source'){const s=await api('commerce_business_source_get',{source_id:b.dataset.id});state.editor={type:'source',source:s};modal('原资料 · v'+s.version,`<p>导入者提供，尚未独立核实。${s.fresh?'仍在填写的有效期内。':'已超过填写的有效期。'}</p><pre>${json(s.document)}</pre><p class="business-digest">SHA256 ${esc(s.sha256)}</p>`,button('导入新版资料','source-update'))}
  else if(action==='source-update'){const s=state.editor.source;await importEditor(s.document,s)}
  else if(action==='import-save'){const document=documentElement('business-import-advanced').checked?JSON.parse(documentElement('business-import-json').value):forms.importValue(state.editor.document);if(document.synthetic!==state.synthetic)throw Error('business_mode_mismatch');if(state.orderContext&&!orderSupport.eligible(document,state.orderContext))throw Error('order_support_scope_mismatch');const source=state.editor.source;await write('commerce_business_import',{document,...source?{source_id:source.id,expected_version:source.version}:{}});closeModal();await refresh();toast('已保存本机资料，来源尚未独立核实。')}
  else if(action==='analyze'){const generation=state.generation;const d=await write('commerce_business_analyze',{source_ids:[...state.selected]});if(generation===state.generation){state.draft=d;await refresh()}}
  else if(action==='compose')await compose();
  else if(action==='edit')await compose(state.draft.draft.kind,state.draft);
  else if(action==='draft-save'){const generation=state.generation,editor=state.editor,content=documentElement('business-content-advanced').checked?JSON.parse(documentElement('business-content-json').value):forms.draftValue(editor.template,editor.content,editor.sources);const saved=editor.orderContext?await write('commerce_order_support_draft',orderSupport.request(editor.orderContext,editor.sources,content,editor.previous)):await write('commerce_business_draft',{kind:editor.kind,source_ids:editor.ids,content,...editor.parent?{parent_id:editor.parent}:{}});if(generation===state.generation)state.draft=saved;closeModal();await refresh();toast('草稿已保存，请查看缺项与依据检查。')}
  else if(action==='open'){const draft=await api('commerce_business_get',{draft_id:b.dataset.id});state.draft=draft;state.orderContext=draft.order_context?.context||null;if(state.orderContext){state.synthetic=state.orderContext.scope.demo;state.sourceScope=orderSupport.scopeKey(state.orderContext);state.selected.clear()}}
  else if(action==='review'||action==='reject'){state.draft=await api('commerce_business_get',{draft_id:state.draft.id});const d=state.draft;state.editor={type:'review',draftId:d.id,sha:d.draft.draft_sha256,decision:action==='review'?'reviewed':'rejected'};modal(action==='review'?'记录本地审阅':'驳回本地草稿',`<p>${esc(scope(d.draft.scope))}</p><pre>${json(d.draft.content.fields)}</pre><p data-ui-help>请核对当前字段、引用版本、平台规则和文案。此记录仅限本机草稿，有效期15分钟；不会执行平台操作。</p><label class="business-source-label"><input type="checkbox" id="business-review-confirm">我已核对当前草稿及其引用，确认记录这次本地${action==='review'?'审阅':'驳回'}。</label><label class="field">审阅备注<textarea id="business-review-note" class="ui-control" maxlength="1000"></textarea></label><p id="business-modal-error" role="alert"></p>`,button('确认记录','review-save',{id:'business-review-save'}))}
  else if(action==='review-save'){if(!documentElement('business-review-confirm').checked)throw Error('business_explicit_local_review_required');const e=state.editor;await write('commerce_business_review',{draft_id:e.draftId,expected_sha256:e.sha,decision:e.decision,confirmed:true,note:documentElement('business-review-note').value});closeModal();state.draft=await api('commerce_business_get',{draft_id:e.draftId});await refresh();toast('已记录本地审阅，未执行平台操作。')}
  else if(action==='export'){const r=await api('commerce_business_export',{draft_id:state.draft.id});download(r.filename,r.content);toast('已导出私有业务证据，请保留在本机。')}
 }
 function cancelEditor(){state.editorRequest++;state.editorPending=false;state.editor=null}
 function beginEditor(){state.editorPending=true;for(const id of ['business-import-save','business-draft-save']){const button=document.getElementById(id);if(button)button.disabled=true}return {id:++state.editorRequest,generation:state.generation,page:state.page,synthetic:state.synthetic}}
 const editorCurrent=t=>t.id===state.editorRequest&&t.generation===state.generation&&t.page===state.page&&t.synthetic===state.synthetic&&active();
 function endEditor(t){if(t.id!==state.editorRequest)return;state.editorPending=false;for(const id of ['business-import-save','business-draft-save']){const button=document.getElementById(id);if(button)button.disabled=false}}
 const documentElement=id=>document.getElementById(id);
 document.addEventListener('click',async event=>{const b=event.target.closest('[data-business-action]');if(!b||!active()||state.busy)return;state.busy=true;const controls=[...document.querySelectorAll('.business-root button,.business-root input,.business-root select,.dialog [data-business-action],#business-kind,#business-import-json,#business-file,#business-content-json,#business-review-confirm,#business-review-note')].map(el=>[el,el.disabled]);for(const [el]of controls)el.disabled=true;try{await execute(b)}catch(e){const messageText=e instanceof SyntaxError?'JSON格式不正确，编辑内容已保留。':e.message==='business_mode_mismatch'?'资料的synthetic与当前输入范围不同，请先核对。':message(e);const target=documentElement('business-modal-error');if(target)target.textContent=messageText;else{state.error=messageText;toast(messageText)}}finally{state.busy=false;for(const [el,disabled]of controls)if(el.isConnected)el.disabled=disabled;if(active()&&!document.querySelector('.dialog'))repaint()}});
 document.addEventListener('change',async event=>{const el=event.target;if(el.matches('[data-business-source]')){const source=state.board?.sources.find(source=>source.id===el.dataset.businessSource);if(el.checked&&(!source||!inSourceScope(source))){el.checked=false;toast(errors.business_scope_mismatch);return}if(el.checked)state.selected.add(el.dataset.businessSource);else state.selected.delete(el.dataset.businessSource);if(active())repaint()}
  else if(el.id==='business-source-scope'){if(state.orderContext){if(active())repaint();return}state.sourceScope=el.value;state.sourceLimit=8;if(state.selected.size){state.selected.clear();toast('已切换资料范围，请重新选择资料。')}if(active())repaint()}
  else if(el.id==='business-source-kind'){state.sourceKind=el.value;state.sourceLimit=8;if(active())repaint()}
  else if(el.id==='business-mode'){if(state.orderContext){toast(errors.order_support_scope_mismatch);if(active())repaint();return}state.synthetic=el.value==='synthetic';state.board=null;state.selected.clear();state.draft=null;state.sourceScope='';state.sourceQuery='';state.sourceLimit=8;await enter(state.page)}
  else if(el.id==='business-file'){try{const file=el.files[0];if(!file)return;if(file.size>450000)throw Error();const raw=await file.text();JSON.parse(raw);documentElement('business-import-json').value=raw;documentElement('business-import-advanced').checked=true;documentElement('business-modal-error').textContent=''}catch{documentElement('business-modal-error').textContent='文件过大或不是有效JSON。原编辑内容已保留。'}}
  else if(el.id==='business-import-kind'){try{await importEditor(null,null,el.value)}catch(e){toast(message(e))}}
  else if(el.id==='business-import-advanced'&&el.checked){documentElement('business-import-json').value=JSON.stringify(forms.importValue(state.editor.document),null,2)}
  else if(el.id==='business-content-advanced'&&el.checked){const e=state.editor;documentElement('business-content-json').value=JSON.stringify(forms.draftValue(e.template,e.content,e.sources),null,2)}
  else if(el.id==='business-kind'){try{await compose(el.value)}catch(e){toast(message(e))}}
 });
 function context(){
  const value={module:state.page==='support'?'support':'insights',demo:state.synthetic},c=state.orderContext;
  if(c){value.platform=c.scope.platform;value.market=c.scope.market;if(/^[A-Za-z0-9_.:-]{1,160}$/.test(c.order.id))value.entity={kind:'order',id:c.order.id}}
  return value;
 }
 function pageContext(){
  const c=state.orderContext,bound=state.draft?.order_context,stale=!!c&&bound?.context?.context_sha256===c.context_sha256&&bound.status!=='current';
  const value={page:state.page==='support'?'support':'insights',section:state.draft?'details':'sources',demo:state.synthetic,source:stale?'stale':'local',filters:{},source_refs:{},errors:[state.error].filter(Boolean)};
  if(c){value.filters={platform:c.scope.platform,store_ref:c.scope.store_id,market:c.scope.market};if(/^[A-Za-z0-9_.:/-]{1,180}$/.test(c.order.id))value.entity={kind:'order',id:c.order.id};value.source_refs=Object.fromEntries(Object.entries({record:c.order.record_sha256,order:c.order.source_sha256,order_context:c.context_sha256,import_batch:c.order.batch_sha256}).filter(([,sha])=>typeof sha==='string'&&/^[a-f0-9]{64}$/.test(sha)))}
  return value;
 }
 return {view,enter,enterOrderSupport,cancelEditor,context,pageContext,errorText:message};
};
