  async function openRelatedAlertOrder(alert){
    if(state.demo)throw Error('请先切换到真实资料范围，再核对此店铺订单。');
    const route=navigationGeneration;
    const result=await api('commerce_orders_list',{demo:false,platform:alert.platform,store_id:'all',market:alert.market,query:alert.order_id});
    if(route!==navigationGeneration||state.demo||state.tab!=='alerts')return;
    const matches=result.orders.filter(order=>order.id===alert.order_id&&order.platform===alert.platform&&order.market===alert.market&&[order.store_id,order.store].includes(alert.store_id)&&order.source_sha256===alert.source_sha256);
    if(matches.length!==1)throw Error('提醒来源已变化或订单范围不匹配，请刷新提醒后重新核对。');
    const order=matches[0];
    dialog('订单详情 · '+order.id,orderDetail(order),btn('核对经营快照','open-live-snapshot'));
  }
